1	package main
2	
3	import (
4		"context"
5		"crypto/sha256"
6		"encoding/hex"
7		"errors"
8		"log"
9		"net/http"
10		"strings"
11	)
12	
13	type ctxKey int
14	
15	const (
16		userKey ctxKey = iota
17		accountKey
18	)
19	
20	// authenticate resolves the bearer token to a user id and stores it in the
21	// request context. Requests without a valid token are rejected with 401.
22	func (s *Server) authenticate(next http.Handler) http.Handler {
23		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
24			token, ok := strings.CutPrefix(r.Header.Get("Authorization"), "Bearer ")
25			if !ok || token == "" {
26				writeErr(w, http.StatusUnauthorized, "missing bearer token")
27				return
28			}
29			userID, err := s.store.UserForToken(r.Context(), hashToken(token))
30			if errors.Is(err, ErrNotFound) {
31				writeErr(w, http.StatusUnauthorized, "invalid token")
32				return
33			}
34			if err != nil {
35				log.Printf("auth: %v", err)
36				writeErr(w, http.StatusInternalServerError, "internal error")
37				return
38			}
39			ctx := context.WithValue(r.Context(), userKey, userID)
40			next.ServeHTTP(w, r.WithContext(ctx))
41		})
42	}
43	
44	// requireOwner loads the account named by the {id} path segment and rejects
45	// the request unless it belongs to the authenticated user. The loaded account
46	// is passed on in the request context.
47	func (s *Server) requireOwner(next http.HandlerFunc) http.HandlerFunc {
48		return func(w http.ResponseWriter, r *http.Request) {
49			id, err := pathID(r)
50			if err != nil {
51				writeErr(w, http.StatusBadRequest, err.Error())
52				return
53			}
54			acct, err := s.store.GetAccount(r.Context(), id)
55			if err != nil {
56				writeStoreError(w, "load account", err)
57				return
58			}
59			if acct.OwnerID != userFrom(r.Context()) {
60				// Same answer as a missing account, so ids cannot be probed.
61				writeErr(w, http.StatusNotFound, "not found")
62				return
63			}
64			ctx := context.WithValue(r.Context(), accountKey, acct)
65			next(w, r.WithContext(ctx))
66		}
67	}
68	
69	func userFrom(ctx context.Context) int64 {
70		id, _ := ctx.Value(userKey).(int64)
71		return id
72	}
73	
74	func accountFrom(ctx context.Context) Account {
75		acct, _ := ctx.Value(accountKey).(Account)
76		return acct
77	}
78	
79	func hashToken(token string) string {
80		sum := sha256.Sum256([]byte(token))
81		return hex.EncodeToString(sum[:])
82	}
83

1	package main
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"log"
8		"net/http"
9		"strconv"
10		"time"
11	)
12	
13	// maxPayoutCents is the largest single payout the API accepts.
14	const maxPayoutCents = 25_000_000
15	
16	// ServerOptions are the tunables of the HTTP layer.
17	type ServerOptions struct {
18		MaxPageSize int
19		NotifyWait  time.Duration
20		DailyLimit  int64
21		Location    *time.Location
22	}
23	
24	// Server holds the dependencies of the HTTP handlers.
25	type Server struct {
26		store    *Store
27		notifier *Notifier
28		payouts  *PayoutClient
29		opts     ServerOptions
30	}
31	
32	type accountJSON struct {
33		ID           int64     `json:"id"`
34		Currency     string    `json:"currency"`
35		BalanceCents int64     `json:"balance_cents"`
36		CreatedAt    time.Time `json:"created_at"`
37	}
38	
39	type entryJSON struct {
40		ID          int64     `json:"id"`
41		AmountCents int64     `json:"amount_cents"`
42		Amount      string    `json:"amount"`
43		Kind        string    `json:"kind"`
44		Reference   string    `json:"reference,omitempty"`
45		CreatedAt   time.Time `json:"created_at"`
46	}
47	
48	func toEntryJSON(e Entry, currency string) entryJSON {
49		return entryJSON{
50			ID:          e.ID,
51			AmountCents: e.AmountCents,
52			Amount:      FormatAmount(e.AmountCents, currency),
53			Kind:        e.Kind,
54			Reference:   e.Reference,
55			CreatedAt:   e.CreatedAt,
56		}
57	}
58	
59	func (s *Server) getAccount(w http.ResponseWriter, r *http.Request) {
60		acct := accountFrom(r.Context())
61		writeJSON(w, http.StatusOK, accountJSON{
62			ID:           acct.ID,
63			Currency:     acct.Currency,
64			BalanceCents: acct.BalanceCents,
65			CreatedAt:    acct.CreatedAt,
66		})
67	}
68	
69	func (s *Server) listEntries(w http.ResponseWriter, r *http.Request) {
70		acct := accountFrom(r.Context())
71		q := r.URL.Query()
72	
73		limit := s.opts.MaxPageSize
74		if v := q.Get("limit"); v != "" {
75			n, err := strconv.Atoi(v)
76			if err != nil || n <= 0 {
77				writeErr(w, http.StatusBadRequest, "limit must be a positive integer")
78				return
79			}
80			limit = min(n, s.opts.MaxPageSize)
81		}
82		var before int64
83		if v := q.Get("before"); v != "" {
84			n, err := strconv.ParseInt(v, 10, 64)
85			if err != nil || n <= 0 {
86				writeErr(w, http.StatusBadRequest, "before must be a positive entry id")
87				return
88			}
89			before = n
90		}
91	
92		entries, err := s.store.ListEntries(r.Context(), acct.ID, before, limit)
93		if err != nil {
94			writeStoreError(w, "list entries", err)
95			return
96		}
97		out := make([]entryJSON, 0, len(entries))
98		for _, e := range entries {
99			out = append(out, toEntryJSON(e, acct.Currency))
100		}
101		writeJSON(w, http.StatusOK, map[string]any{"entries": out})
102	}
103	
104	type depositRequest struct {
105		AmountCents int64  `json:"amount_cents"`
106		Reference   string `json:"reference"`
107	}
108	
109	func (s *Server) createDeposit(w http.ResponseWriter, r *http.Request) {
110		acct := accountFrom(r.Context())
111		var req depositRequest
112		if err := decodeJSON(r, &req); err != nil {
113			writeErr(w, http.StatusBadRequest, err.Error())
114			return
115		}
116		if req.AmountCents <= 0 {
117			writeErr(w, http.StatusBadRequest, "amount_cents must be positive")
118			return
119		}
120	
121		e, err := s.store.Credit(r.Context(), acct.ID, req.AmountCents, "deposit", req.Reference)
122		if err != nil {
123			writeStoreError(w, "deposit", err)
124			return
125		}
126		s.notify(Event{Type: "deposit", AccountID: acct.ID, AmountCents: e.AmountCents, Reference: e.Reference, At: e.CreatedAt})
127		writeJSON(w, http.StatusCreated, toEntryJSON(e, acct.Currency))
128	}
129	
130	type payoutRequest struct {
131		AmountCents int64  `json:"amount_cents"`
132		Destination string `json:"destination"`
133	}
134	
135	func (s *Server) createPayout(w http.ResponseWriter, r *http.Request) {
136		acct := accountFrom(r.Context())
137		var req payoutRequest
138		if err := decodeJSON(r, &req); err != nil {
139			writeErr(w, http.StatusBadRequest, err.Error())
140			return
141		}
142		if req.AmountCents <= 0 || req.AmountCents > maxPayoutCents {
143			writeErr(w, http.StatusBadRequest, fmt.Sprintf("amount_cents must be between 1 and %d", maxPayoutCents))
144			return
145		}
146		if req.Destination == "" {
147			writeErr(w, http.StatusBadRequest, "destination is required")
148			return
149		}
150	
151		ref, err := newReference("po")
152		if err != nil {
153			writeStoreError(w, "payout reference", err)
154			return
155		}
156		e, err := s.store.Withdraw(r.Context(), acct.ID, req.AmountCents, ref)
157		if err != nil {
158			writeStoreError(w, "payout debit", err)
159			return
160		}
161	
162		res, err := s.payouts.Send(r.Context(), PayoutRequest{
163			AmountCents: req.AmountCents,
164			Currency:    acct.Currency,
165			Destination: req.Destination,
166			Reference:   ref,
167		})
168		if err != nil {
169			log.Printf("payout %s for account %d failed: %v", ref, acct.ID, err)
170			if _, rerr := s.store.Credit(r.Context(), acct.ID, req.AmountCents, "payout_reversal", ref); rerr != nil {
171				log.Printf("payout %s: reversal failed, manual fix needed: %v", ref, rerr)
172			}
173			writeErr(w, http.StatusBadGateway, "payout provider did not accept the payout")
174			return
175		}
176	
177		s.notify(Event{Type: "payout", AccountID: acct.ID, AmountCents: e.AmountCents, Reference: ref, At: e.CreatedAt})
178		writeJSON(w, http.StatusAccepted, map[string]any{
179			"entry":       toEntryJSON(e, acct.Currency),
180			"provider_id": res.ProviderID,
181			"status":      res.Status,
182		})
183	}
184	
185	// notify sends ev to the webhook, waiting at most opts.NotifyWait.
186	func (s *Server) notify(ev Event) {
187		if err := s.notifier.NotifyWithin(ev, s.opts.NotifyWait); err != nil {
188			log.Printf("notify %s for account %d: %v", ev.Type, ev.AccountID, err)
189		}
190	}
191	
192	// pathID parses the {id} path segment.
193	func pathID(r *http.Request) (int64, error) {
194		id, err := strconv.ParseInt(r.PathValue("id"), 10, 64)
195		if err != nil || id <= 0 {
196			return 0, errors.New("invalid id in path")
197		}
198		return id, nil
199	}
200	
201	// decodeJSON reads a small JSON body into dst and rejects unknown fields.
202	func decodeJSON(r *http.Request, dst any) error {
203		dec := json.NewDecoder(http.MaxBytesReader(nil, r.Body, 1<<16))
204		dec.DisallowUnknownFields()
205		if err := dec.Decode(dst); err != nil {
206			return fmt.Errorf("invalid request body: %w", err)
207		}
208		return nil
209	}
210	
211	func writeJSON(w http.ResponseWriter, status int, v any) {
212		w.Header().Set("Content-Type", "application/json")
213		w.WriteHeader(status)
214		if err := json.NewEncoder(w).Encode(v); err != nil {
215			log.Printf("write response: %v", err)
216		}
217	}
218	
219	func writeErr(w http.ResponseWriter, status int, msg string) {
220		writeJSON(w, status, map[string]string{"error": msg})
221	}
222	
223	// writeStoreError maps an error from the store (or a check built on it) to
224	// an HTTP response. Unexpected errors are logged with op and reported as 500.
225	func writeStoreError(w http.ResponseWriter, op string, err error) {
226		switch {
227		case errors.Is(err, ErrNotFound):
228			writeErr(w, http.StatusNotFound, "not found")
229		case errors.Is(err, ErrInsufficientFunds):
230			writeErr(w, http.StatusConflict, "insufficient funds")
231		case errors.Is(err, ErrDailyLimit):
232			writeErr(w, http.StatusUnprocessableEntity, "daily transfer limit reached")
233		default:
234			log.Printf("%s: %v", op, err)
235			writeErr(w, http.StatusInternalServerError, "internal error")
236		}
237	}
