8		"fmt"
9		"io"
10		"log"
11		"net/http"
12		"time"
13	)
14	
15	// PayoutClient sends money from a wallet to an external bank account through
16	// the payout provider's HTTP API.
17	type PayoutClient struct {
18		baseURL     string
19		apiKey      string
20		http        *http.Client
21		maxAttempts int
22		backoff     time.Duration
23	}
24	
25	// PayoutRequest is what the wallet asks the provider to pay out.
26	type PayoutRequest struct {
27		AmountCents int64
28		Currency    string
29		Destination string // provider token for the bank account
30		Reference   string // also sent as the idempotency key
31	}
32	
33	// PayoutResult is the provider's answer to an accepted payout.
34	type PayoutResult struct {
35		ProviderID string `json:"id"`
36		Status     string `json:"status"`
37	}
38	
39	// providerPayout is the provider's wire format.
40	type providerPayout struct {
41		AmountMinor int32  `json:"amount_minor"`
42		Currency    string `json:"currency"`
43		Destination string `json:"destination"`
44		Reference   string `json:"reference"`
45	}
46	
47	// rejectedError is a 4xx answer from the provider. Retrying cannot help.
48	type rejectedError struct {
49		status int
50		body   string
51	}
52	
53	func (e *rejectedError) Error() string {
54		return fmt.Sprintf("payout rejected: status %d: %s", e.status, e.body)
55	}
56	
57	// Send asks the provider to pay out p. Network errors, 429 and 5xx answers
58	// are retried with exponential backoff; the provider deduplicates retries by
59	// the idempotency key.
60	func (c *PayoutClient) Send(ctx context.Context, p PayoutRequest) (PayoutResult, error) {
61		body, err := json.Marshal(providerPayout{
62			AmountMinor: int32(p.AmountCents),
63			Currency:    p.Currency,
64			Destination: p.Destination,
65			Reference:   p.Reference,
66		})
67		if err != nil {
68			return PayoutResult{}, err
69		}
70	
71		var res PayoutResult
72		for attempt := 1; attempt <= c.maxAttempts; attempt++ {
73			if attempt > 1 {
74				select {
75				case <-time.After(c.backoff << (attempt - 2)):
76				case <-ctx.Done():
77					return PayoutResult{}, ctx.Err()
78				}
79			}
80			res, err := c.post(ctx, body, p.Reference)
81			if err == nil {
82				return res, nil
83			}
84			var rejected *rejectedError
85			if errors.As(err, &rejected) {
86				return PayoutResult{}, err
87			}
88			log.Printf("payout %s: attempt %d/%d: %v", p.Reference, attempt, c.maxAttempts, err)
89		}
90		return res, err
91	}
92	
93	func (c *PayoutClient) post(ctx context.Context, body []byte, idempotencyKey string) (PayoutResult, error) {
94		req, err := http.NewRequestWithContext(ctx, http.MethodPost, c.baseURL+"/v1/payouts", bytes.NewReader(body))
95		if err != nil {
96			return PayoutResult{}, err
97		}
98		req.Header.Set("Content-Type", "application/json")
99		req.Header.Set("Authorization", "Bearer "+c.apiKey)
100		req.Header.Set("Idempotency-Key", idempotencyKey)
101	
102		resp, err := c.http.Do(req)
103		if err != nil {
104			return PayoutResult{}, err
105		}
106		if resp.StatusCode == http.StatusTooManyRequests || resp.StatusCode >= 500 {
107			return PayoutResult{}, fmt.Errorf("payout provider: status %d", resp.StatusCode)
108		}
109		defer resp.Body.Close()
110	
111		if resp.StatusCode >= 400 {
112			msg, _ := io.ReadAll(io.LimitReader(resp.Body, 512))
113			return PayoutResult{}, &rejectedError{status: resp.StatusCode, body: string(msg)}
114		}
115		var out PayoutResult
116		if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
117			return PayoutResult{}, fmt.Errorf("decode payout response: %w", err)
118		}
119		return out, nil
120	}
