1	package main
2	
3	import (
4		"context"
5		"crypto/rand"
6		"encoding/hex"
7		"errors"
8		"fmt"
9		"net/http"
10		"time"
11	)
12	
13	// ErrDailyLimit is returned when a transfer would take an account over its
14	// daily transfer limit.
15	var ErrDailyLimit = errors.New("daily transfer limit exceeded")
16	
17	type transferRequest struct {
18		ToAccountID int64  `json:"to_account_id"`
19		AmountCents int64  `json:"amount_cents"`
20		Memo        string `json:"memo"`
21	}
22	
23	// createTransfer moves money from the account in the path to another account
24	// of the same currency.
25	func (s *Server) createTransfer(w http.ResponseWriter, r *http.Request) {
26		from := accountFrom(r.Context())
27		var req transferRequest
28		if err := decodeJSON(r, &req); err != nil {
29			writeErr(w, http.StatusBadRequest, err.Error())
30			return
31		}
32		if req.AmountCents <= 0 || req.ToAccountID == from.ID {
33			writeErr(w, http.StatusBadRequest, "need a positive amount_cents and a different to_account_id")
34			return
35		}
36	
37		to, err := s.store.GetAccount(r.Context(), req.ToAccountID)
38		if err != nil {
39			writeStoreError(w, "load destination account", err)
40			return
41		}
42		if to.Currency != from.Currency {
43			writeErr(w, http.StatusUnprocessableEntity, "accounts use different currencies")
44			return
45		}
46		if from.BalanceCents < req.AmountCents {
47			writeStoreError(w, "transfer", ErrInsufficientFunds)
48			return
49		}
50		if err := s.checkDailyLimit(r.Context(), from.ID, req.AmountCents); err != nil {
51			writeStoreError(w, "check daily limit", err)
52			return
53		}
54	
55		t, err := s.store.CreateTransfer(r.Context(), Transfer{
56			FromAccountID: from.ID,
57			ToAccountID:   to.ID,
58			AmountCents:   req.AmountCents,
59			Memo:          req.Memo,
60		})
61		if err != nil {
62			writeStoreError(w, "create transfer", err)
63			return
64		}
65	
66		ref := transferReference(t.ID)
67		s.notify(Event{Type: "transfer_out", AccountID: from.ID, AmountCents: -t.AmountCents, Reference: ref, At: t.CreatedAt})
68		s.notify(Event{Type: "transfer_in", AccountID: to.ID, AmountCents: t.AmountCents, Reference: ref, At: t.CreatedAt})
69	
70		writeJSON(w, http.StatusCreated, t)
71		w.Header().Set("Location", fmt.Sprintf("/transfers/%d", t.ID))
72	}
73	
74	func (s *Server) getTransfer(w http.ResponseWriter, r *http.Request) {
75		id, err := pathID(r)
76		if err != nil {
77			writeErr(w, http.StatusBadRequest, err.Error())
78			return
79		}
80		t, err := s.store.GetTransfer(r.Context(), id)
81		if err != nil {
82			writeStoreError(w, "get transfer", err)
83			return
84		}
85		writeJSON(w, http.StatusOK, t)
86	}
87	
88	// checkDailyLimit returns ErrDailyLimit if sending amountCents now would take
89	// the account over its limit for the current business day.
90	func (s *Server) checkDailyLimit(ctx context.Context, accountID, amountCents int64) error {
91		if s.opts.DailyLimit <= 0 {
92			return nil
93		}
94		since := startOfBusinessDay(time.Now(), s.opts.Location)
95		sent, err := s.store.SentSince(ctx, accountID, since)
96		if err != nil {
97			return err
98		}
99		if sent+amountCents > s.opts.DailyLimit {
100			return ErrDailyLimit
101		}
102		return nil
103	}
104	
105	// startOfBusinessDay returns midnight at the start of the business day that
106	// contains now.
107	func startOfBusinessDay(now time.Time, loc *time.Location) time.Time {
108		y, m, d := now.UTC().Date()
109		return time.Date(y, m, d, 0, 0, 0, 0, loc)
110	}
111	
112	// newReference returns a random reference such as "po_3f9a0c2b1d4e5f60".
113	func newReference(prefix string) (string, error) {
114		var b [8]byte
115		if _, err := rand.Read(b[:]); err != nil {
116			return "", err
117		}
118		return prefix + "_" + hex.EncodeToString(b[:]), nil
119	}
