1	package main
2	
3	import (
4		"context"
5		"database/sql"
6		"errors"
7		"fmt"
8		"time"
9	)
10	
11	var (
12		// ErrNotFound is returned when a looked-up row does not exist.
13		ErrNotFound = errors.New("not found")
14		// ErrInsufficientFunds is returned when a debit would overdraw an account.
15		ErrInsufficientFunds = errors.New("insufficient funds")
16	)
17	
18	// Account is a single-currency wallet. Balances are kept in minor units
19	// (cents) to avoid floating point.
20	type Account struct {
21		ID           int64
22		OwnerID      int64
23		Currency     string
24		BalanceCents int64
25		CreatedAt    time.Time
26	}
27	
28	// Entry is one line of an account's ledger. AmountCents is positive for
29	// credits and negative for debits.
30	type Entry struct {
31		ID          int64
32		AccountID   int64
33		AmountCents int64
34		Kind        string
35		Reference   string
36		CreatedAt   time.Time
37	}
38	
39	// Transfer moves money between two accounts of the same currency.
40	type Transfer struct {
41		ID            int64     `json:"id"`
42		FromAccountID int64     `json:"from_account_id"`
43		ToAccountID   int64     `json:"to_account_id"`
44		AmountCents   int64     `json:"amount_cents"`
45		Memo          string    `json:"memo,omitempty"`
46		CreatedAt     time.Time `json:"created_at"`
47	}
48	
49	// Store is the persistence layer. All amounts are in minor units.
50	type Store struct {
51		db *sql.DB
52	}
53	
54	func NewStore(db *sql.DB) *Store { return &Store{db: db} }
55	
56	// UserForToken returns the user owning the (hashed) API token.
57	func (s *Store) UserForToken(ctx context.Context, tokenHash string) (int64, error) {
58		var userID int64
59		err := s.db.QueryRowContext(ctx,
60			`SELECT user_id FROM api_tokens WHERE token_hash = ? AND revoked_at IS NULL`,
61			tokenHash).Scan(&userID)
62		if errors.Is(err, sql.ErrNoRows) {
63			return 0, ErrNotFound
64		}
65		if err != nil {
66			return 0, fmt.Errorf("look up token: %w", err)
67		}
68		return userID, nil
69	}
70	
71	func (s *Store) GetAccount(ctx context.Context, id int64) (Account, error) {
72		var a Account
73		err := s.db.QueryRowContext(ctx,
74			`SELECT id, owner_id, currency, balance_cents, created_at FROM accounts WHERE id = ?`, id).
75			Scan(&a.ID, &a.OwnerID, &a.Currency, &a.BalanceCents, &a.CreatedAt)
76		if err != nil {
77			if errors.Is(err, sql.ErrNoRows) {
78				err = ErrNotFound
79			}
80			return Account{}, fmt.Errorf("get account %d: %v", id, err)
81		}
82		return a, nil
83	}
84	
85	// ListEntries returns up to limit entries of an account with an id below
86	// before, newest first. Pass before = 0 to start from the newest entry.
87	func (s *Store) ListEntries(ctx context.Context, accountID, before int64, limit int) ([]Entry, error) {
88		if before <= 0 {
89			before = 1<<63 - 1
90		}
91		rows, err := s.db.QueryContext(ctx,
92			`SELECT id, account_id, amount_cents, kind, reference, created_at
93			   FROM entries
94			  WHERE account_id = ? AND id < ?
95			  ORDER BY id DESC
96			  LIMIT ?`, accountID, before, limit)
97		if err != nil {
98			return nil, fmt.Errorf("list entries: %w", err)
99		}
100		return scanEntries(rows)
101	}
102	
103	// scanEntries reads all rows into entries and closes rows.
104	func scanEntries(rows *sql.Rows) ([]Entry, error) {
105		defer rows.Close()
106		var out []Entry
107		for rows.Next() {
108			var e Entry
109			if err := rows.Scan(&e.ID, &e.AccountID, &e.AmountCents, &e.Kind, &e.Reference, &e.CreatedAt); err != nil {
110				return nil, fmt.Errorf("scan entry: %w", err)
111			}
112			out = append(out, e)
113		}
114		return out, rows.Err()
115	}
116	
117	// SentSince sums the transfers an account has sent since the given time, as
118	// a positive number of cents.
119	func (s *Store) SentSince(ctx context.Context, accountID int64, since time.Time) (int64, error) {
120		var sent int64
121		err := s.db.QueryRowContext(ctx,
122			`SELECT COALESCE(SUM(-amount_cents), 0)
123			   FROM entries
124			  WHERE account_id = ? AND kind = ? AND created_at >= ?`,
125			accountID, "transfer_out", since.UTC()).Scan(&sent)
126		if err != nil {
127			return 0, fmt.Errorf("sum transfers of account %d: %w", accountID, err)
128		}
129		return sent, nil
130	}
131	
132	// Credit adds money to an account and records the matching ledger entry of
133	// the given kind in one transaction.
134	func (s *Store) Credit(ctx context.Context, accountID, amountCents int64, kind, reference string) (Entry, error) {
135		tx, err := s.db.BeginTx(ctx, nil)
136		if err != nil {
137			return Entry{}, err
138		}
139		defer tx.Rollback()
140	
141		if err := adjustBalance(ctx, tx, accountID, amountCents); err != nil {
142			return Entry{}, err
143		}
144		e, err := insertEntry(ctx, tx, Entry{
145			AccountID:   accountID,
146			AmountCents: amountCents,
147			Kind:        kind,
148			Reference:   reference,
149		})
150		if err != nil {
151			return Entry{}, err
152		}
153		return e, tx.Commit()
154	}
155	
156	// Withdraw debits an account for a payout.
157	func (s *Store) Withdraw(ctx context.Context, accountID, amountCents int64, reference string) (Entry, error) {
158		tx, err := s.db.BeginTx(ctx, nil)
159		if err != nil {
160			return Entry{}, err
161		}
162		defer tx.Rollback()
163	
164		res, err := tx.ExecContext(ctx,
165			`UPDATE accounts SET balance_cents = balance_cents - ? WHERE id = ? AND balance_cents >= ?`,
166			amountCents, accountID, amountCents)
167		if err != nil {
168			return Entry{}, fmt.Errorf("debit account %d: %w", accountID, err)
169		}
170		if n, err := res.RowsAffected(); err != nil {
171			return Entry{}, err
172		} else if n == 0 {
173			return Entry{}, ErrInsufficientFunds
174		}
175	
176		e, err := insertEntry(ctx, tx, Entry{
177			AccountID:   accountID,
178			AmountCents: -amountCents,
179			Kind:        "payout",
180			Reference:   reference,
181		})
182		if err != nil {
183			return Entry{}, err
184		}
185		return e, tx.Commit()
186	}
187	
188	// CreateTransfer records a transfer, moves the money and writes one ledger
189	// entry on each side, all in one transaction.
190	func (s *Store) CreateTransfer(ctx context.Context, t Transfer) (Transfer, error) {
191		tx, err := s.db.BeginTx(ctx, nil)
192		if err != nil {
193			return Transfer{}, fmt.Errorf("begin transfer: %w", err)
194		}
195		defer func() {
196			if err != nil {
197				_ = tx.Rollback()
198				return
199			}
200			err = tx.Commit()
201		}()
202	
203		t.CreatedAt = time.Now().UTC()
204		res, err := tx.ExecContext(ctx,
205			`INSERT INTO transfers (from_account_id, to_account_id, amount_cents, memo, created_at)
206			 VALUES (?, ?, ?, ?, ?)`,
207			t.FromAccountID, t.ToAccountID, t.AmountCents, t.Memo, t.CreatedAt)
208		if err != nil {
209			return Transfer{}, fmt.Errorf("insert transfer: %w", err)
210		}
211		if t.ID, err = res.LastInsertId(); err != nil {
212			return Transfer{}, err
213		}
214	
215		if err := adjustBalance(ctx, tx, t.FromAccountID, -t.AmountCents); err != nil {
216			return Transfer{}, fmt.Errorf("debit account %d: %w", t.FromAccountID, err)
217		}
218		if err := adjustBalance(ctx, tx, t.ToAccountID, t.AmountCents); err != nil {
219			return Transfer{}, fmt.Errorf("credit account %d: %w", t.ToAccountID, err)
220		}
221	
222		ref := transferReference(t.ID)
223		for _, e := range []Entry{
224			{AccountID: t.FromAccountID, AmountCents: -t.AmountCents, Kind: "transfer_out", Reference: ref},
225			{AccountID: t.ToAccountID, AmountCents: t.AmountCents, Kind: "transfer_in", Reference: ref},
226		} {
227			if _, err := insertEntry(ctx, tx, e); err != nil {
228				return Transfer{}, err
229			}
230		}
231		return t, nil
232	}
233	
234	func (s *Store) GetTransfer(ctx context.Context, id int64) (Transfer, error) {
235		var t Transfer
236		err := s.db.QueryRowContext(ctx,
237			`SELECT id, from_account_id, to_account_id, amount_cents, memo, created_at FROM transfers WHERE id = ?`, id).
238			Scan(&t.ID, &t.FromAccountID, &t.ToAccountID, &t.AmountCents, &t.Memo, &t.CreatedAt)
239		if errors.Is(err, sql.ErrNoRows) {
240			return Transfer{}, ErrNotFound
241		}
242		if err != nil {
243			return Transfer{}, fmt.Errorf("get transfer %d: %w", id, err)
244		}
245		return t, nil
246	}
