192	// pathID parses the {id} path segment.
193	func pathID(r *http.Request) (int64, error) {
194		id, err := strconv.ParseInt(r.PathValue("id"), 10, 64)
195		if err != nil || id <= 0 {
196			return 0, errors.New("invalid id in path")
197		}
198		return id, nil
199	}
200	
201	// decodeJSON reads a small JSON body into dst and rejects unknown fields.
202	func decodeJSON(r *http.Request, dst any) error {
203		dec := json.NewDecoder(http.MaxBytesReader(nil, r.Body, 1<<16))
204		dec.DisallowUnknownFields()
205		if err := dec.Decode(dst); err != nil {
206			return fmt.Errorf("invalid request body: %w", err)
207		}
208		return nil
209	}
210	
211	func writeJSON(w http.ResponseWriter, status int, v any) {
212		w.Header().Set("Content-Type", "application/json")
213		w.WriteHeader(status)
214		if err := json.NewEncoder(w).Encode(v); err != nil {
215			log.Printf("write response: %v", err)
216		}
217	}
218	
219	func writeErr(w http.ResponseWriter, status int, msg string) {
220		writeJSON(w, status, map[string]string{"error": msg})
221	}
222	
223	// writeStoreError maps an error from the store (or a check built on it) to
224	// an HTTP response. Unexpected errors are logged with op and reported as 500.
225	func writeStoreError(w http.ResponseWriter, op string, err error) {
226		switch {
227		case errors.Is(err, ErrNotFound):
228			writeErr(w, http.StatusNotFound, "not found")
229		case errors.Is(err, ErrInsufficientFunds):
230			writeErr(w, http.StatusConflict, "insufficient funds")
231		case errors.Is(err, ErrDailyLimit):
232			writeErr(w, http.StatusUnprocessableEntity, "daily transfer limit reached")
233		default:
234			log.Printf("%s: %v", op, err)
235			writeErr(w, http.StatusInternalServerError, "internal error")
236		}
237	}
