 10	// Config holds the service settings. Every field can be set from the
 11	// environment; see LoadConfig for the variable names and defaults.
 12	type Config struct {
 13		Addr     string
 14		DBDriver string
 15		DSN      string
 16	
 17		// MaxPageSize caps the number of ledger entries returned per page.
 18		MaxPageSize int
 19	
 20		// WebhookURL receives account events. Empty disables notifications.
 21		WebhookURL     string
 22		WebhookTimeout time.Duration
 23		NotifyWait     time.Duration // how long a request waits for the webhook
 24	
 25		// DailyTransferLimit is the most one account may send to other accounts
 26		// per business day, in whole currency units (1000 means 1,000.00).
 27		// Zero disables the limit.
 28		DailyTransferLimit int64
 29		// BusinessLocation decides when a business day starts and ends.
 30		BusinessLocation *time.Location
 31	
 32		PayoutURL     string
 33		PayoutAPIKey  string
 34		PayoutTimeout time.Duration
 35	}
 36	
 37	// LoadConfig reads the configuration from the environment.
 38	func LoadConfig() (Config, error) {
 39		cfg := Config{
 40			Addr:               envOr("WALLET_ADDR", ":8080"),
 41			DBDriver:           envOr("WALLET_DB_DRIVER", "sqlite"),
 42			DSN:                envOr("WALLET_DSN", "file:wallet.db"),
 43			MaxPageSize:        100,
 44			WebhookURL:         os.Getenv("WALLET_WEBHOOK_URL"),
 45			WebhookTimeout:     5 * time.Second,
 46			NotifyWait:         300 * time.Millisecond,
 47			DailyTransferLimit: 1000,
 48			PayoutURL:          envOr("WALLET_PAYOUT_URL", "https://payouts.example.invalid"),
 49			PayoutAPIKey:       os.Getenv("WALLET_PAYOUT_API_KEY"),
 50			PayoutTimeout:      10 * time.Second,
 51		}
 52	
 53		if v := os.Getenv("WALLET_MAX_PAGE_SIZE"); v != "" {
 54			n, err := strconv.Atoi(v)
 55			if err != nil || n <= 0 {
 56				return Config{}, fmt.Errorf("WALLET_MAX_PAGE_SIZE: want a positive integer, got %q", v)
 57			}
 58			cfg.MaxPageSize = n
 59		}
 60		if v := os.Getenv("WALLET_DAILY_TRANSFER_LIMIT"); v != "" {
 61			n, err := strconv.ParseInt(v, 10, 64)
 62			if err != nil || n < 0 {
 63				return Config{}, fmt.Errorf("WALLET_DAILY_TRANSFER_LIMIT: want a non-negative integer, got %q", v)
 64			}
 65			cfg.DailyTransferLimit = n
 66		}
 67		for key, dst := range map[string]*time.Duration{
 68			"WALLET_WEBHOOK_TIMEOUT": &cfg.WebhookTimeout,
 69			"WALLET_NOTIFY_WAIT":     &cfg.NotifyWait,
 70			"WALLET_PAYOUT_TIMEOUT":  &cfg.PayoutTimeout,
 71		} {
 72			if v := os.Getenv(key); v != "" {
 73				d, err := time.ParseDuration(v)
 74				if err != nil {
 75					return Config{}, fmt.Errorf("%s: %w", key, err)
 76				}
 77				*dst = d
 78			}
 79		}
 80	
 81		loc, err := time.LoadLocation(envOr("WALLET_BUSINESS_TZ", "America/New_York"))
 82		if err != nil {
 83			return Config{}, fmt.Errorf("WALLET_BUSINESS_TZ: %w", err)
 84		}
 85		cfg.BusinessLocation = loc
 86		return cfg, nil
 87	}
 88	
 89	func envOr(key, def string) string {
 90		if v := os.Getenv(key); v != "" {
 91			return v
 92		}
 93		return def
 94	}
