 56	func (s *Server) routes() http.Handler {
 57		mux := http.NewServeMux()
 58		mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, r *http.Request) {
 59			w.WriteHeader(http.StatusNoContent)
 60		})
 61	
 62		owned := func(h http.HandlerFunc) http.Handler {
 63			return s.authenticate(s.requireOwner(h))
 64		}
 65		mux.Handle("GET /accounts/{id}", owned(s.getAccount))
 66		mux.Handle("GET /accounts/{id}/entries", owned(s.listEntries))
 67		mux.Handle("POST /accounts/{id}/deposits", owned(s.createDeposit))
 68		mux.Handle("POST /accounts/{id}/transfers", owned(s.createTransfer))
 69		mux.Handle("POST /accounts/{id}/payouts", owned(s.createPayout))
 70		mux.Handle("GET /transfers/{id}", owned(s.getTransfer))
 71		return logRequests(mux)
 72	}
