 74	type statusRecorder struct {
 75		http.ResponseWriter
 76		status int
 77	}
 78	
 79	func (r *statusRecorder) WriteHeader(code int) {
 80		r.status = code
 81		r.ResponseWriter.WriteHeader(code)
 82	}
 83	
 84	func logRequests(next http.Handler) http.Handler {
 85		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
 86			start := time.Now()
 87			rec := &statusRecorder{ResponseWriter: w, status: http.StatusOK}
 88			next.ServeHTTP(rec, r)
 89			log.Printf("%s %s %d %s", r.Method, r.URL.Path, rec.status, time.Since(start).Round(time.Millisecond))
 90		})
 91	}
