 69	func (s *Server) listEntries(w http.ResponseWriter, r *http.Request) {
 70		acct := accountFrom(r.Context())
 71		q := r.URL.Query()
 72	
 73		limit := s.opts.MaxPageSize
 74		if v := q.Get("limit"); v != "" {
 75			n, err := strconv.Atoi(v)
 76			if err != nil || n <= 0 {
 77				writeErr(w, http.StatusBadRequest, "limit must be a positive integer")
 78				return
 79			}
 80			limit = min(n, s.opts.MaxPageSize)
 81		}
 82		var before int64
 83		if v := q.Get("before"); v != "" {
 84			n, err := strconv.ParseInt(v, 10, 64)
 85			if err != nil || n <= 0 {
 86				writeErr(w, http.StatusBadRequest, "before must be a positive entry id")
 87				return
 88			}
 89			before = n
 90		}
 91	
 92		entries, err := s.store.ListEntries(r.Context(), acct.ID, before, limit)
 93		if err != nil {
 94			writeStoreError(w, "list entries", err)
 95			return
 96		}
 97		out := make([]entryJSON, 0, len(entries))
 98		for _, e := range entries {
 99			out = append(out, toEntryJSON(e, acct.Currency))
100		}
101		writeJSON(w, http.StatusOK, map[string]any{"entries": out})
102	}
