135	func (s *Server) createPayout(w http.ResponseWriter, r *http.Request) {
136		acct := accountFrom(r.Context())
137		var req payoutRequest
138		if err := decodeJSON(r, &req); err != nil {
139			writeErr(w, http.StatusBadRequest, err.Error())
140			return
141		}
142		if req.AmountCents <= 0 || req.AmountCents > maxPayoutCents {
143			writeErr(w, http.StatusBadRequest, fmt.Sprintf("amount_cents must be between 1 and %d", maxPayoutCents))
144			return
145		}
146		if req.Destination == "" {
147			writeErr(w, http.StatusBadRequest, "destination is required")
148			return
149		}
150	
151		ref, err := newReference("po")
152		if err != nil {
153			writeStoreError(w, "payout reference", err)
154			return
155		}
156		e, err := s.store.Withdraw(r.Context(), acct.ID, req.AmountCents, ref)
157		if err != nil {
158			writeStoreError(w, "payout debit", err)
159			return
160		}
161	
162		res, err := s.payouts.Send(r.Context(), PayoutRequest{
163			AmountCents: req.AmountCents,
164			Currency:    acct.Currency,
165			Destination: req.Destination,
166			Reference:   ref,
167		})
168		if err != nil {
169			log.Printf("payout %s for account %d failed: %v", ref, acct.ID, err)
170			if _, rerr := s.store.Credit(r.Context(), acct.ID, req.AmountCents, "payout_reversal", ref); rerr != nil {
171				log.Printf("payout %s: reversal failed, manual fix needed: %v", ref, rerr)
172			}
173			writeErr(w, http.StatusBadGateway, "payout provider did not accept the payout")
174			return
175		}
176	
177		s.notify(Event{Type: "payout", AccountID: acct.ID, AmountCents: e.AmountCents, Reference: ref, At: e.CreatedAt})
178		writeJSON(w, http.StatusAccepted, map[string]any{
179			"entry":       toEntryJSON(e, acct.Currency),
180			"provider_id": res.ProviderID,
181			"status":      res.Status,
182		})
183	}
