234	func (s *Store) GetTransfer(ctx context.Context, id int64) (Transfer, error) {
235		var t Transfer
236		err := s.db.QueryRowContext(ctx,
237			`SELECT id, from_account_id, to_account_id, amount_cents, memo, created_at FROM transfers WHERE id = ?`, id).
238			Scan(&t.ID, &t.FromAccountID, &t.ToAccountID, &t.AmountCents, &t.Memo, &t.CreatedAt)
239		if errors.Is(err, sql.ErrNoRows) {
240			return Transfer{}, ErrNotFound
241		}
242		if err != nil {
243			return Transfer{}, fmt.Errorf("get transfer %d: %w", id, err)
244		}
245		return t, nil
246	}
