  8	// currencyInfo describes how a currency's minor units are written.
  9	type currencyInfo struct {
 10		Code     string
 11		Exponent int // number of minor-unit digits, e.g. 2 for USD
 12	}
 13	
 14	var currencies = map[string]currencyInfo{}
 15	
 16	func init() {
 17		for _, c := range []currencyInfo{
 18			{Code: "USD", Exponent: 2},
 19			{Code: "EUR", Exponent: 2},
 20			{Code: "GBP", Exponent: 2},
 21			{Code: "CAD", Exponent: 2},
 22			{Code: "JPY", Exponent: 0},
 23		} {
 24			currencies[c.Code] = c
 25		}
 26	}
 27	
 28	// FormatAmount renders an amount in minor units as a decimal string for
 29	// display, e.g. 12345 USD -> "123.45" and 500 JPY -> "500".
 30	func FormatAmount(minor int64, currency string) string {
 31		info, ok := currencies[currency]
 32		if !ok || info.Exponent == 0 {
 33			return strconv.FormatInt(minor, 10)
 34		}
 35		scale := int64(1)
 36		for i := 0; i < info.Exponent; i++ {
 37			scale *= 10
 38		}
 39		return fmt.Sprintf("%d.%0*d", minor/scale, info.Exponent, minor%scale)
 40	}
