1	package main
2	
3	import (
4		"context"
5		"crypto/sha256"
6		"encoding/hex"
7		"errors"
8		"log"
9		"net/http"
10		"strings"
11	)
12	
13	type ctxKey int
14	
15	const (
16		userKey ctxKey = iota
17		accountKey
18	)
19	
20	// authenticate resolves the bearer token to a user id and stores it in the
21	// request context. Requests without a valid token are rejected with 401.
22	func (s *Server) authenticate(next http.Handler) http.Handler {
23		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
24			token, ok := strings.CutPrefix(r.Header.Get("Authorization"), "Bearer ")
25			if !ok || token == "" {
26				writeErr(w, http.StatusUnauthorized, "missing bearer token")
27				return
28			}
29			userID, err := s.store.UserForToken(r.Context(), hashToken(token))
30			if errors.Is(err, ErrNotFound) {
31				writeErr(w, http.StatusUnauthorized, "invalid token")
32				return
33			}
34			if err != nil {
35				log.Printf("auth: %v", err)
36				writeErr(w, http.StatusInternalServerError, "internal error")
37				return
38			}
39			ctx := context.WithValue(r.Context(), userKey, userID)
40			next.ServeHTTP(w, r.WithContext(ctx))
41		})
42	}
43	
44	// requireOwner loads the account named by the {id} path segment and rejects
45	// the request unless it belongs to the authenticated user. The loaded account
46	// is passed on in the request context.
47	func (s *Server) requireOwner(next http.HandlerFunc) http.HandlerFunc {
48		return func(w http.ResponseWriter, r *http.Request) {
49			id, err := pathID(r)
50			if err != nil {
51				writeErr(w, http.StatusBadRequest, err.Error())
52				return
53			}
54			acct, err := s.store.GetAccount(r.Context(), id)
55			if err != nil {
56				writeStoreError(w, "load account", err)
57				return
58			}
59			if acct.OwnerID != userFrom(r.Context()) {
60				// Same answer as a missing account, so ids cannot be probed.
61				writeErr(w, http.StatusNotFound, "not found")
62				return
63			}
64			ctx := context.WithValue(r.Context(), accountKey, acct)
65			next(w, r.WithContext(ctx))
66		}
67	}
68	
69	func userFrom(ctx context.Context) int64 {
70		id, _ := ctx.Value(userKey).(int64)
71		return id
72	}
73	
74	func accountFrom(ctx context.Context) Account {
75		acct, _ := ctx.Value(accountKey).(Account)
76		return acct
77	}
78	
79	func hashToken(token string) string {
80		sum := sha256.Sum256([]byte(token))
81		return hex.EncodeToString(sum[:])
82	}
