1	package main
2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"io"
10		"net/http"
11		"time"
12	)
13	
14	var errNotifyTimeout = errors.New("webhook did not answer in time")
15	
16	// Event is posted to the configured webhook when money moves.
17	type Event struct {
18		Type        string    `json:"type"`
19		AccountID   int64     `json:"account_id"`
20		AmountCents int64     `json:"amount_cents"`
21		Reference   string    `json:"reference,omitempty"`
22		At          time.Time `json:"at"`
23	}
24	
25	// Notifier delivers events to a webhook endpoint.
26	type Notifier struct {
27		url    string
28		client *http.Client
29	}
30	
31	func NewNotifier(url string, timeout time.Duration) *Notifier {
32		return &Notifier{url: url, client: &http.Client{Timeout: timeout}}
33	}
34	
35	// NotifyWithin delivers ev but stops waiting for the webhook after wait, so a
36	// slow endpoint cannot hold up an API response.
37	func (n *Notifier) NotifyWithin(ev Event, wait time.Duration) error {
38		if n.url == "" {
39			return nil
40		}
41		done := make(chan error)
42		go func() {
43			// Not tied to the request context: the request may finish first.
44			done <- n.Notify(context.Background(), ev)
45		}()
46		select {
47		case err := <-done:
48			return err
49		case <-time.After(wait):
50			return errNotifyTimeout
51		}
52	}
53	
54	// Notify posts ev to the webhook. It is a no-op when no URL is configured.
55	func (n *Notifier) Notify(ctx context.Context, ev Event) error {
56		if n.url == "" {
57			return nil
58		}
59		body, err := json.Marshal(ev)
60		if err != nil {
61			return err
62		}
63		req, err := http.NewRequestWithContext(ctx, http.MethodPost, n.url, bytes.NewReader(body))
64		if err != nil {
65			return err
66		}
67		req.Header.Set("Content-Type", "application/json")
68	
69		resp, err := n.client.Do(req)
70		if err != nil {
71			return err
72		}
73		defer resp.Body.Close()
74		_, _ = io.Copy(io.Discard, resp.Body)
75	
76		if resp.StatusCode >= 300 {
77			return fmt.Errorf("webhook: unexpected status %d", resp.StatusCode)
78		}
79		return nil
80	}
